CREATE TYPE "VendorAdObjective" AS ENUM ('AWARENESS','TRAFFIC','ORDERS');
CREATE TABLE "vendor_advertising_campaigns" ("id" TEXT NOT NULL,"vendorId" TEXT NOT NULL,"outletId" TEXT,"name" TEXT NOT NULL,"objective" "VendorAdObjective" NOT NULL DEFAULT 'ORDERS',"status" TEXT NOT NULL DEFAULT 'DRAFT',"budgetAmount" INTEGER NOT NULL,"spendAmount" INTEGER NOT NULL DEFAULT 0,"impressions" INTEGER NOT NULL DEFAULT 0,"clicks" INTEGER NOT NULL DEFAULT 0,"conversions" INTEGER NOT NULL DEFAULT 0,"revenueAmount" INTEGER NOT NULL DEFAULT 0,"startsAt" TIMESTAMP(3) NOT NULL,"endsAt" TIMESTAMP(3) NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "vendor_advertising_campaigns_pkey" PRIMARY KEY ("id"));
CREATE TABLE "vendor_advertising_campaign_products" ("campaignId" TEXT NOT NULL,"productId" TEXT NOT NULL,CONSTRAINT "vendor_advertising_campaign_products_pkey" PRIMARY KEY ("campaignId","productId"));
CREATE INDEX "vendor_advertising_campaigns_vendorId_status_startsAt_endsAt_idx" ON "vendor_advertising_campaigns"("vendorId","status","startsAt","endsAt");CREATE INDEX "vendor_advertising_campaigns_outletId_idx" ON "vendor_advertising_campaigns"("outletId");CREATE INDEX "vendor_advertising_campaign_products_productId_idx" ON "vendor_advertising_campaign_products"("productId");
ALTER TABLE "vendor_advertising_campaigns" ADD CONSTRAINT "vendor_advertising_campaigns_vendorId_fkey" FOREIGN KEY ("vendorId") REFERENCES "vendors"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "vendor_advertising_campaigns" ADD CONSTRAINT "vendor_advertising_campaigns_outletId_fkey" FOREIGN KEY ("outletId") REFERENCES "outlets"("id") ON DELETE SET NULL ON UPDATE CASCADE;ALTER TABLE "vendor_advertising_campaign_products" ADD CONSTRAINT "vendor_advertising_campaign_products_campaignId_fkey" FOREIGN KEY ("campaignId") REFERENCES "vendor_advertising_campaigns"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "vendor_advertising_campaign_products" ADD CONSTRAINT "vendor_advertising_campaign_products_productId_fkey" FOREIGN KEY ("productId") REFERENCES "products"("id") ON DELETE CASCADE ON UPDATE CASCADE;
